// Extract data from PennyPilot webhook
const body = $input.first().json.body || $input.first().json;
const { session_id, user_message, action, context } = body;

// User context for AI
const identity = context?.identity || {};
const bossGoal = context?.boss_goal || {};
const stats = context?.stats || {};
const quadrants = context?.quadrants || {};
const missing = context?.missing_fields || [];

// Build the full prompt
const systemContext = `You are Penny, a stoic financial co-pilot.

Rules:
- Direct and efficient, minimal fluff
- Use **bold** for emphasis
- Keep responses under 80 words
- NEVER ask for data already known

== KNOWN USER DATA ==
Name: ${identity.name || 'Unknown'}
Age: ${identity.age || 'Unknown'}
Client: ${identity.client || 'Unknown'}
Level: ${stats.level || 1} | XP: ${stats.total_xp || 0} | Streak: ${stats.quest_streak || 0}d

== BOSS GOAL ==
${bossGoal.name ? bossGoal.name + ': R' + Number(bossGoal.target || 0).toLocaleString() + ' (' + (bossGoal.progress_percent || 0) + '%)' : 'NOT SET'}

== QUADRANT STATUS ==
DO: ${quadrants.has_quests ? 'Has data' : 'EMPTY'}
HAVE: ${quadrants.has_inventory ? 'Has data' : 'EMPTY'}
BE: ${quadrants.has_traits ? 'Has data' : 'EMPTY'}
LIVE: ${quadrants.has_destination ? 'Set' : 'EMPTY'}

== CAN ASK ABOUT ==
${missing.length > 0 ? missing.join(', ') : 'None'}

== ACTION ==
${action || 'chat'}`;

const fullPrompt = systemContext + '\n\nUser: ' + (user_message || 'Hello');

return {
  prompt: fullPrompt,
  session_id,
  action
};

// Get the AI Agent output
const response = $input.first().json;

// AI Agent returns: { state: "...", cities: [] }
// or sometimes: { text: "..." } or { output: "..." }
let replyText = response.state || response.text || response.output || '';

// If it's an object, try to extract text
if (typeof replyText === 'object') {
  replyText = replyText.text || replyText.state || JSON.stringify(replyText);
}

// Clean up the response
replyText = String(replyText).trim();

// If empty, provide fallback
if (!replyText) {
  replyText = 'Ready. What can I help with?';
}

return {
  reply: replyText,
  action: null,
  memory_updates: null
};
